package org.eclipse.rdf4j.sail.lmdb.benchmark;

import java.util.concurrent.atomic.LongAdder;

import org.eclipse.rdf4j.sail.lmdb.LmdbBenchmarkQueryPlan.PlanningCompletion;
import org.eclipse.rdf4j.sail.lmdb.LmdbBenchmarkQueryPlan.PlanningPath;
import org.eclipse.rdf4j.sail.lmdb.LmdbBenchmarkQueryPlan.PlanningReceipt;

/** Per-state counts derived directly from each preparation's receipt. */
final class PlanningReceiptCounts {
	private final LongAdder[] paths = counters(PlanningPath.values().length);
	private final LongAdder[] completions = counters(PlanningCompletion.values().length);

	void record(PlanningReceipt receipt) {
		paths[receipt.path().ordinal()].increment();
		completions[receipt.completion().ordinal()].increment();
	}

	void reportAndReset(String benchmark) {
		StringBuilder report = new StringBuilder("planningReceipts benchmark=").append(benchmark);
		long total = 0L;
		for (PlanningPath path : PlanningPath.values()) {
			long count = paths[path.ordinal()].sumThenReset();
			total += count;
			report.append(" path.").append(path.name()).append('=').append(count);
		}
		for (PlanningCompletion completion : PlanningCompletion.values()) {
			report.append(" completion.")
					.append(completion.name())
					.append('=')
					.append(completions[completion.ordinal()].sumThenReset());
		}
		if (total != 0L) {
			System.out.println(report);
		}
	}

	private static LongAdder[] counters(int size) {
		LongAdder[] counters = new LongAdder[size];
		for (int index = 0; index < size; index++) {
			counters[index] = new LongAdder();
		}
		return counters;
	}
}
